def handle_a(item):
    value = item["value"] * 2
    category = "high" if value > 100 else "low"
    return {"id": item["id"], "value": value, "category": category}


def handle_b(item):
    value = item["value"] + 50
    return {"id": item["id"], "value": value, "category": "adjusted"}


def handle_c(item):
    if item["value"] < 0:
        return {"id": item["id"], "value": 0, "category": "clamped"}
    return {"id": item["id"], "value": item["value"], "category": "passthrough"}


HANDLERS = {
    "A": handle_a,
    "B": handle_b,
    "C": handle_c,
}


def dispatch(item):
    handler = HANDLERS.get(item.get("type"))
    if handler is None:
        return None
    return handler(item)


def process_data(data):
    results = []
    for item in data:
        result = dispatch(item)
        if result is not None:
            results.append(result)
    return results
