interface User {
    id: number;
    name: string;
    email: string;
    preferences: Preferences;
    tags: string[];
    last_login: string; // ISO 8601 date-time string
    metadata?: unknown | null; // optional, may be absent or explicitly null
}

function validateUser(user: any): user is User {
    if (typeof user !== 'object' || user === null) return false;

    // id: integer (number in TS)
    if (typeof user.id !== 'number') return false;

    // name: non-empty string
    if (typeof user.name !== 'string' || user.name.length === 0) return false;

    // email: string containing "@"
    if (typeof user.email !== 'string' || !user.email.includes('@')) return false;

    // preferences: object with required fields
    const prefs = user.preferences;
    if (typeof prefs !== 'object' || prefs === null) return false;
    if (typeof prefs.theme !== 'string') return false;
    if (typeof prefs.notifications !== 'boolean') return false;
    if (typeof prefs.language !== 'string') return false;

    // tags: array of strings
    if (!Array.isArray(user.tags)) return false;
    for (const tag of user.tags) {
        if (typeof tag !== 'string') return false;
    }

    // last_login: string (ISO 8601 format expected)
    if (typeof user.last_login !== 'string') return false;

    // metadata is optional and nullable — no further validation needed

    return true;
}
