#!/usr/bin/env python3
"""Log level analyzer CLI tool.

Scans .log files in a directory and reports counts of each log level.

Usage:
    python log_analyzer.py /path/to/logs
    python log_analyzer.py ./logs --min-errors 5
"""

import argparse
import os
import re
import sys


def parse_args():
    parser = argparse.ArgumentParser(
        description="Analyze .log files and count occurrences of each log level.",
        epilog="Example: %(prog)s /var/log/myapp --min-errors 3",
    )
    parser.add_argument(
        "directory",
        nargs="?",
        default=".",
        help="Directory containing .log files (default: current directory)",
    )
    parser.add_argument(
        "--min-errors",
        type=int,
        default=0,
        metavar="N",
        help="Only show files with at least N errors (default: 0 = all files)",
    )
    return parser.parse_args()


def count_log_levels(filepath):
    """Count occurrences of each log level in a single file.

    Matches INFO, WARN/WARNING, ERROR, DEBUG as whole words (case-insensitive).
    WARNING is normalized to WARN.
    """
    levels = {"INFO": 0, "WARN": 0, "ERROR": 0, "DEBUG": 0}
    pattern = re.compile(r"\b(INFO|WARN|WARNING|ERROR|DEBUG)\b", re.IGNORECASE)

    try:
        with open(filepath, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                match = pattern.search(line)
                if match:
                    level = match.group(1).upper()
                    if level == "WARNING":
                        level = "WARN"
                    levels[level] += 1
    except (IOError, OSError) as e:
        print(f"Warning: Could not read {filepath}: {e}", file=sys.stderr)

    return levels


def format_table(results):
    """Format results into an aligned text table with a totals row."""
    header = ["file", "INFO", "WARN", "ERROR", "DEBUG"]

    # Build data rows
    rows = []
    for filename, counts in results:
        rows.append([
            filename,
            str(counts["INFO"]),
            str(counts["WARN"]),
            str(counts["ERROR"]),
            str(counts["DEBUG"]),
        ])

    # Compute totals
    totals = {"INFO": 0, "WARN": 0, "ERROR": 0, "DEBUG": 0}
    for _, counts in results:
        for level in totals:
            totals[level] += counts[level]
    total_row = [
        "TOTAL",
        str(totals["INFO"]),
        str(totals["WARN"]),
        str(totals["ERROR"]),
        str(totals["DEBUG"]),
    ]

    # Calculate column widths
    col_widths = [len(h) for h in header]
    all_rows = rows + [total_row]
    for row in all_rows:
        for i, cell in enumerate(row):
            col_widths[i] = max(col_widths[i], len(cell))

    # Format a single row with alignment (file left-aligned, numbers right)
    def fmt_row(row):
        cells = []
        for i, cell in enumerate(row):
            if i == 0:
                cells.append(cell.ljust(col_widths[i]))
            else:
                cells.append(cell.rjust(col_widths[i]))
        return " | ".join(cells)

    separator = "-+-".join("-" * w for w in col_widths)

    lines = [fmt_row(header), separator]
    for row in rows:
        lines.append(fmt_row(row))
    lines.append(separator)
    lines.append(fmt_row(total_row))

    return "\n".join(lines)


def main():
    args = parse_args()
    directory = args.directory

    if not os.path.isdir(directory):
        print(f"Error: '{directory}' is not a valid directory.", file=sys.stderr)
        sys.exit(1)

    # Find all .log files (non-recursive, sorted for deterministic output)
    try:
        entries = os.listdir(directory)
    except OSError as e:
        print(f"Error: Could not list directory '{directory}': {e}", file=sys.stderr)
        sys.exit(1)

    log_files = sorted([
        f for f in entries
        if f.endswith(".log") and os.path.isfile(os.path.join(directory, f))
    ])

    if not log_files:
        print(f"No .log files found in '{directory}'.")
        sys.exit(0)

    # Analyze each file and apply --min-errors filter
    results = []
    for filename in log_files:
        filepath = os.path.join(directory, filename)
        counts = count_log_levels(filepath)
        if counts["ERROR"] >= args.min_errors:
            results.append((filename, counts))

    if not results:
        print(f"No files with >= {args.min_errors} error(s) found.")
        sys.exit(0)

    # Output the summary table
    print(format_table(results))


if __name__ == "__main__":
    main()
```
